+      background: rgba(15, 23, 42, 0.9);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+    }
+
+    input[type="checkbox"] {
+      width: 20px;
+      height: 20px;
+      margin-top: 2px;
+      accent-color: var(--accent);
+      cursor: pointer;
+      flex: 0 0 auto;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.45;
+      cursor: pointer;
+    }
+
+    .helper-text,
+    .error-text,
+    .status {
+      margin-top: 10px;
+      font-size: 0.95rem;
+      line-height: 1.4;
+    }
+
+    .helper-text {
+      color: var(--muted);
+    }
+
+    .error-text {
+      color: #fca5a5;
+      min-height: 1.4em;
+    }
+
+    button {
+      margin-top: 20px;
+      width: 100%;
+      border: 0;
+      border-radius: 14px;
+      padding: 14px 18px;
+      font: inherit;
+      font-weight: 700;
+      color: var(--accent-contrast);
+      background: linear-gradient(180deg, #93c5fd, var(--accent-strong));
+      cursor: pointer;
+      box-shadow: 0 10px 30px rgba(59, 130, 246, 0.35);
+      transition: transform 120ms ease, box-shadow 120ms ease;
+    }
+
+    button:hover {
+      transform: translateY(-1px);
+      box-shadow: 0 14px 34px rgba(59, 130, 246, 0.42);
+    }
+
+    button:active {
+      transform: translateY(0);
+    }
+
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 3px;
+    }
+
+    .status {
+      display: none;
+      padding: 12px 14px;
+      border: 1px solid var(--success-border);
+      border-radius: 12px;
+      color: var(--success-text);
+      background: var(--success-bg);
+    }
+
+    .status[data-visible="true"] {
+      display: block;
+      margin-top: 18px;
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 24px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      body {
+        background: Canvas;
+        color: CanvasText;
+      }
+
+      .card,
+      .form-field,
+      .status {
+        background: Canvas;
+        color: CanvasText;
+        border-color: ButtonText;
+        box-shadow: none;
+      }
+
+      .skip-link,
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+        border: 1px solid ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content">
+    <section class="card" aria-labelledby="form-title">
+      <h1 id="form-title">Confirm your consent</h1>
+      <p>Please review the terms and confirm your agreement before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="terms-consent"
+              name="termsConsent"
+              type="checkbox"
+              required
+              aria-describedby="terms-help terms-error"
+            >
+            <label for="terms-consent">I agree to the terms of use.</label>
+          </div>
+          <p id="terms-help" class="helper-text">Required to continue.</p>
+          <p id="terms-error" class="error-text" aria-live="assertive"></p>
+        </div>
+
+        <button type="submit">Submit</button>
+        <p id="form-status" class="status" aria-live="polite">Consent submitted successfully.</p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms-consent');
+    const errorText = document.getElementById('terms-error');
+    const status = document.getElementById('form-status');
+
+    const syncValidation = () => {
+      if (checkbox.checked) {
+        checkbox.setCustomValidity('');
+        checkbox.removeAttribute('aria-invalid');
+        errorText.textContent = '';
+        return true;
+      }
+
+      checkbox.setCustomValidity('Please agree to the terms of use before submitting.');
+      checkbox.setAttribute('aria-invalid', 'true');
+      errorText.textContent = checkbox.validationMessage;
+      return false;
+    };
+
+    checkbox.addEventListener('change', () => {
+      syncValidation();
+      if (checkbox.checked) {
+        status.dataset.visible = 'false';
+      }
+    });
+
+    form.addEventListener('submit', (event) => {
+      const isValid = syncValidation();
+
+      if (!isValid) {
+        event.preventDefault();
+        checkbox.focus();
+        status.dataset.visible = 'false';
+        return;
+      }
+
+      event.preventDefault();
+      status.dataset.visible = 'true';
+      form.reset();
+      checkbox.removeAttribute('aria-invalid');
+      errorText.textContent = '';
+    });
+  </script>
+</body>
+</html>
*** End Patch
