  <title>Terms Consent Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: #111827;
      --panel-border: #253047;
      --text: #f3f4f6;
      --muted: #a5b4cc;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --accent-contrast: #08111f;
      --success-bg: #0f2f1e;
      --success-border: #2f855a;
      --success-text: #d1fae5;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 35%),
